import React from 'react';
import styled from 'styled-components';

const AboutSection = styled.section`
  max-width: 700px;
  margin: 0 auto;
  padding: 6rem 1.5rem 3rem 1.5rem;
  color: #fff;
`;

const Heading = styled.h2`
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 2rem;
  color: #fff;
`;

const Text = styled.p`
  font-size: 1.15rem;
  color: #aaa;
  line-height: 1.7;
`;

const About = () => (
  <AboutSection id="about">
    <Heading>About Me</Heading>
    <Text>
      I’m a passionate frontend developer focused on building clean, performant, and accessible web interfaces. I love solving complex UI problems and turning ideas into delightful user experiences. My approach blends technical skill with a strong UI/UX mindset, always striving for elegant, maintainable solutions.
    </Text>
  </AboutSection>
);

export default About;
